mapper.select:
/*selectJobIdExists*/
SELECT COUNT(1)
  FROM TB_S_BATCH_JOB_CTRL
 WHERE JOB_ID = #{job_id}

mapper.update:
/*updateJobCtrl*/
UPDATE TB_S_BATCH_JOB_CTRL
   SET JOB_NAME = #{job_name}
     , ENABLE_YN = #{enable_yn}
     , INTERVAL_MIN = TO_NUMBER(#{interval_min})
     , LIMIT_CNT = TO_NUMBER(#{limit_cnt})
     , STALE_DAYS = TO_NUMBER(#{stale_days})
     , COUNTRY_CODE = #{country_code}
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}

mapper.select:
/*selectTryLock*/
SELECT RUNNING_YN
  FROM TB_S_BATCH_JOB_CTRL
 WHERE JOB_ID = #{job_id}

mapper.update:
/*finish*/
UPDATE TB_S_BATCH_JOB_CTRL
   SET RUNNING_YN = 'N'
     , LAST_END_DT = SYSDATE
     , LAST_RESULT_CODE = #{last_result_code}
     , LAST_RESULT_MSG = #{last_result_msg}
     , LAST_RUN_CNT = TO_NUMBER(#{last_run_cnt})
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}

/*forceClearRunning*/
UPDATE TB_S_BATCH_JOB_CTRL
   SET RUNNING_YN = 'N'
     , LAST_END_DT = SYSDATE
     , LAST_RESULT_CODE = 'ERROR'
     , LAST_RESULT_MSG = #{last_result_msg}
     , MOD_DT = SYSDATE
 WHERE JOB_ID = #{job_id}
   AND RUNNING_YN = 'Y'

mapper.select:
/*selectRefreshTargets*/ SELECT * FROM ( SELECT STOCK_ID ,STOCK_CODE ,STOCK_COUNTRY_CODE ,USE_DIV ,MODIFY_DATE ,STOCK_KO_NAME ,STOCK_EN_NAME ,STOCK_SECTOR ,STOCK_MARKET ,MARKET_SECTION ,STOCK_TYPE ,STOCK_TYPE_SPECS ,STOCK_CURRENCY ,STOCK_TIMEZONE ,STOCK_ALIASES FROM TB_S_INTEREST_STOCK WHERE 1=1 AND USE_DIV = 'Y'
AND STOCK_COUNTRY_CODE = #{stock_country_code}
AND ( MODIFY_DATE IS NULL OR MODIFY_DATE < (SYSDATE - TO_NUMBER(#{stale_days})) OR STOCK_KO_NAME IS NULL OR STOCK_MARKET IS NULL OR STOCK_SECTOR IS NULL OR STOCK_TYPE IS NULL OR STOCK_TYPE_SPECS IS NULL OR STOCK_CURRENCY IS NULL OR STOCK_TIMEZONE IS NULL ) ORDER BY NVL(MODIFY_DATE, TO_DATE('19000101','YYYYMMDD')) ASC ) WHERE ROWNUM <= TO_NUMBER(#{limit})

mapper.update:
/*updateInterestStockMeta*/
UPDATE TB_S_INTEREST_STOCK
   SET STOCK_KO_NAME = #{stock_ko_name}
     , STOCK_EN_NAME = #{stock_en_name}
     , STOCK_SECTOR = #{stock_sector}
     , STOCK_MARKET = #{stock_market}
     , MARKET_SECTION = #{market_section}
     , STOCK_TYPE = #{stock_type}
     , STOCK_TYPE_SPECS = #{stock_type_specs}
     , STOCK_CURRENCY = #{stock_currency}
     , STOCK_TIMEZONE = #{stock_timezone}
     , STOCK_ALIASES = #{stock_aliases}
     , USE_DIV = #{use_div}
     , MODIFY_DATE = SYSDATE
 WHERE STOCK_ID = #{stock_id}

/*touchModifyDate*/
UPDATE TB_S_INTEREST_STOCK
   SET MODIFY_DATE = SYSDATE
 WHERE STOCK_ID = #{stock_id}

/*disableTaggedInterestStock*/ UPDATE TB_S_INTEREST_STOCK SET USE_DIV = 'N' , MODIFY_DATE = SYSDATE WHERE 1=1
AND STOCK_COUNTRY_CODE = #{stock_country_code}
AND STOCK_ALIASES LIKE '%' || #{tag} || '%'
